insert into public.chapters (id, title_da, description_ua, intro_ua) values (1, 'Sygdom & fravær', 'Фрази, які допоможуть повідомити про хворобу, запізнення, відсутність і повернення на роботу.', 'Повідомити про хворобу данською простіше, ніж здається. Данці пишуть коротко: що сталося і коли приблизно повернетеся. Без довгих пояснень і вибачень.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(1, 1, 'Jeg er syg i dag og kan ikke komme på arbejde.', 'Я сьогодні хвора і не можу прийти на роботу.', 'Найуніверсальніша фраза. Підходить і для SMS, і для дзвінка.'),
(1, 2, 'Jeg har det ikke godt i dag.', 'Я сьогодні погано почуваюся.', null),
(1, 3, 'Jeg bliver nødt til at blive hjemme i dag.', 'Мені доведеться залишитися сьогодні вдома.', '«Blive nødt til» означає «бути змушеною». Дуже частий вираз: jeg bliver nødt til at gå, jeg bliver nødt til at ringe.'),
(1, 4, 'Jeg kan desværre ikke komme på arbejde.', 'На жаль, я не можу прийти на роботу.', null),
(1, 5, 'Jeg har feber.', 'У мене температура.', null),
(1, 6, 'Jeg har ondt i halsen.', 'У мене болить горло.', null),
(1, 7, 'Jeg har hovedpine.', 'У мене болить голова.', null),
(1, 8, 'Jeg har været syg siden i går.', 'Я хворію ще з учора.', null),
(1, 9, 'Jeg giver besked, når jeg har det bedre.', 'Я повідомлю, коли мені стане краще.', null),
(1, 10, 'Hvornår forventer du at være tilbage?', 'Коли ти очікуєш повернутися?', null),
(1, 11, 'Jeg håber at være tilbage i morgen.', 'Я сподіваюся повернутися завтра.', null),
(1, 12, 'Jeg er stadig syg og bliver hjemme i dag.', 'Я все ще хвора і сьогодні залишаюся вдома.', null),
(1, 13, 'Jeg har en lægetid i dag.', 'У мене сьогодні прийом у лікаря.', null),
(1, 14, 'Jeg skal til lægen.', 'Мені потрібно до лікаря.', null),
(1, 15, 'Jeg sender dokumentationen senere.', 'Я надішлю підтвердження пізніше.', 'Іноді роботодавець просить підтвердження від лікаря (lægeerklæring). Уточніть, які правила діють на вашій роботі.'),
(1, 16, 'Jeg beklager det sene varsel.', 'Перепрошую за таке пізнє повідомлення.', 'Varsel означає попередження. Цю фразу добре додати, якщо пишете зранку в останній момент.'),
(1, 17, 'Jeg melder mig syg i dag.', 'Я хочу повідомити, що я хвора.', '«Melde sig syg» це стійкий вираз, саме так кажуть данці. Дослівно: «заявляю себе хворою». Є й протилежне: «melde sig rask», тобто повідомити, що ви знову здорові.'),
(1, 18, 'Skal jeg ringe til dig senere?', 'Мені зателефонувати тобі пізніше?', null),
(1, 19, 'Jeg er ikke i stand til at arbejde i dag.', 'Я не можу працювати сьогодні.', null),
(1, 20, 'Jeg regner med at være tilbage på mandag.', 'Я планую повернутися в понеділок.', '«Regne med» означає розраховувати, планувати. Звучить впевнено, але не як обіцянка.'),
(1, 21, 'Jeg giver besked, hvis noget ændrer sig.', 'Я повідомлю, якщо щось зміниться.', null),
(1, 22, 'Jeg er blevet dårlig i løbet af dagen.', 'Мені стало погано протягом дня.', null),
(1, 23, 'Jeg bliver nødt til at gå hjem.', 'Мені доведеться піти додому.', null),
(1, 24, 'Er det okay, at jeg går hjem?', 'Чи можна мені піти додому?', null),
(1, 25, 'Jeg føler mig bedre nu.', 'Зараз я почуваюся краще.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (1, 1, 'Дзвінок начальнику зранку', '[{"who":"Anna","da":"Godmorgen, det er Anna. Jeg ringer for at melde mig syg.","ua":"Доброго ранку, це Анна. Я телефоную, щоб повідомити, що захворіла.","me":true},{"who":"Chef","da":"Åh, det var ærgerligt. Hvad er der galt?","ua":"Ой, шкода. Що сталося?","me":false},{"who":"Anna","da":"Jeg har feber og ondt i halsen.","ua":"У мене температура і болить горло.","me":true},{"who":"Chef","da":"Okay. Hvornår forventer du at være tilbage?","ua":"Добре. Коли ти очікуєш повернутися?","me":false},{"who":"Anna","da":"Jeg håber at være tilbage i morgen. Jeg giver besked, hvis noget ændrer sig.","ua":"Сподіваюся повернутися завтра. Я повідомлю, якщо щось зміниться.","me":true},{"who":"Chef","da":"Fint. God bedring!","ua":"Добре. Одужуй!","me":false}]'::jsonb);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (1, 2, 'Стало погано на роботі', '[{"who":"Anna","da":"Undskyld, jeg er blevet dårlig i løbet af dagen.","ua":"Вибач, мені стало погано протягом дня.","me":true},{"who":"Chef","da":"Du ser heller ikke så godt ud. Har du brug for at gå hjem?","ua":"Ти й справді не дуже добре виглядаєш. Тобі треба піти додому?","me":false},{"who":"Anna","da":"Ja. Er det okay, at jeg går hjem?","ua":"Так. Чи можна мені піти додому?","me":true},{"who":"Chef","da":"Selvfølgelig. Pas på dig selv.","ua":"Звісно. Бережи себе.","me":false}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (1, 1, 'Данці повідомляють про хворобу дуже коротко, без довгих пояснень. Не потрібно розповідати всі симптоми. Достатньо сказати «Jeg melder mig syg i dag» і коли приблизно повернетеся. Це звучить нормально й професійно, а не грубо.');
insert into public.notes (chapter_id, sort, body_ua) values (1, 2, 'Фраза «God bedring!» означає «Одужуй!». Ви почуєте її майже завжди, коли скажете, що захворіли. Відповісти можна просто: «Tak!»');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (1, 1, 'Jeg er syk i dag.', 'Jeg er syg i dag.', '«Syk» це норвезька. Данською буде «syg», а «g» в кінці майже не чутно.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (1, 2, 'Jeg har en feber.', 'Jeg har feber.', 'Про хворобу данці кажуть без артикля: jeg har feber, jeg har hovedpine, jeg har ondt i halsen.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (1, 3, 'Jeg føler mig ikke godt.', 'Jeg har det ikke godt.', 'Про самопочуття данці кажуть «Jeg har det godt / ikke godt», дослівно «я маю це добре». Звучить незвично, але саме так природно.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (1, 1, 'Керівнику, SMS зранку', 'Hej, jeg er desværre syg i dag og kan ikke komme på arbejde. Jeg giver besked, når jeg ved mere.', 'Привіт, на жаль, я сьогодні хвора і не можу прийти на роботу. Я повідомлю, коли знатиму більше.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (1, 2, 'Керівнику, другий день', 'Hej, jeg er stadig syg og bliver hjemme i dag. Jeg regner med at være tilbage i morgen.', 'Привіт, я все ще хвора і сьогодні залишаюся вдома. Планую повернутися завтра.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (1, 3, 'Колегам, коли повернулися', 'Hej alle sammen, jeg er tilbage i dag. Tak, fordi I dækkede for mig.', 'Привіт усім, я сьогодні повернулася. Дякую, що підмінили мене.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (1, 1, 'Що сказати начальнику, якщо ти захворіла?', '["Jeg har ferie.","Jeg kommer tidligere.","Jeg er syg."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (1, 2, 'Як сказати «У мене болить голова»?', '["Jeg har feber.","Jeg har hovedpine.","Jeg har ondt i halsen."]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (1, 3, 'Як природно сказати «Я сьогодні погано почуваюся»?', '["Jeg har det ikke godt i dag.","Jeg føler mig ikke godt i dag.","Jeg er ikke god i dag."]'::jsonb, 0, 'Про самопочуття кажуть «Jeg har det godt / ikke godt».');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (1, 4, 'Колега каже вам «God bedring!». Що це означає?', '["Гарного дня!","Побачимося завтра!","Одужуй!"]'::jsonb, 2, null);
insert into public.vocab (chapter_id, sort, da, ua) values (1, 1, 'syg', 'хворий, хвора'), (1, 2, 'sygdom', 'хвороба'), (1, 3, 'fravær', 'відсутність'), (1, 4, 'feber', 'температура'), (1, 5, 'hovedpine', 'головний біль'), (1, 6, 'ondt i halsen', 'біль у горлі'), (1, 7, 'læge', 'лікар'), (1, 8, 'lægetid', 'прийом у лікаря'), (1, 9, 'god bedring', 'одужуй'), (1, 10, 'varsel', 'попередження');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (2, 'Arbejdstid & vagtplan', 'Практична лексика для змін, графіка, перерв, вихідних і робочих годин.', 'Графік змін, перерви, запізнення і вихідні. Тут фрази, щоб домовитися про час без стресу, і слова, які ви точно побачите у vagtplan.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(2, 1, 'Hvornår starter min vagt?', 'Коли починається моя зміна?', null),
(2, 2, 'Hvornår slutter min vagt?', 'Коли закінчується моя зміна?', null),
(2, 3, 'Hvilken vagt har jeg i morgen?', 'Яка в мене зміна завтра?', null),
(2, 4, 'Kan du sende mig vagtplanen?', 'Можеш надіслати мені графік?', null),
(2, 5, 'Jeg kan arbejde på mandag.', 'Я можу працювати в понеділок.', null),
(2, 6, 'Jeg kan ikke arbejde på fredag.', 'Я не можу працювати в п''ятницю.', null),
(2, 7, 'Kan jeg bytte vagt med en kollega?', 'Чи можу я помінятися зміною з колегою?', '«Bytte» означає обмінятися. «Bytte vagt» це поміняти зміну з колегою. Дуже часто так кажуть у магазинах, лікарнях і на складах.'),
(2, 8, 'Jeg har brug for at bytte min vagt.', 'Мені потрібно поміняти мою зміну.', null),
(2, 9, 'Kan jeg tage en ekstra vagt?', 'Чи можу я взяти додаткову зміну?', null),
(2, 10, 'Er der flere timer til mig?', 'Чи є для мене ще години роботи?', null),
(2, 11, 'Hvor mange timer arbejder jeg i denne uge?', 'Скільки годин я працюю цього тижня?', null),
(2, 12, 'Hvornår har jeg pause?', 'Коли в мене перерва?', 'Перерва може бути оплачуваною (betalt pause) або ні (ubetalt pause). Це залежить від вашого договору.'),
(2, 13, 'Hvor lang er min pause?', 'Скільки триває моя перерва?', null),
(2, 14, 'Må jeg tage min pause nu?', 'Можна мені зараз піти на перерву?', null),
(2, 15, 'Jeg kommer ti minutter senere.', 'Я прийду на десять хвилин пізніше.', null),
(2, 16, 'Jeg er på vej.', 'Я вже в дорозі.', 'Датське «Jeg er på vej» дуже зручне в повсякденному спілкуванні. Його можна використовувати, коли ви вже виходите, їдете або прямуєте кудись. Не обов''язково перекладати дослівно як «я на шляху».'),
(2, 17, 'Jeg er lidt forsinket.', 'Я трохи запізнююся.', null),
(2, 18, 'Jeg er her nu.', 'Я вже тут.', null),
(2, 19, 'Jeg kan blive lidt længere i dag.', 'Я можу сьогодні залишитися трохи довше.', null),
(2, 20, 'Kan jeg gå lidt tidligere i dag?', 'Чи можу я сьогодні піти трохи раніше?', null),
(2, 21, 'Jeg har en aftale efter arbejde.', 'У мене є зустріч після роботи.', null),
(2, 22, 'Jeg har fri i morgen.', 'У мене завтра вихідний.', '«Have fri» означає мати вихідний. «Fridag» це вихідний день.'),
(2, 23, 'Jeg arbejder i weekenden.', 'Я працюю на вихідних.', null),
(2, 24, 'Hvornår får jeg min næste vagtplan?', 'Коли я отримаю наступний графік?', null),
(2, 25, 'Kan vi tale om mine arbejdstider?', 'Можемо поговорити про мій робочий графік?', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (2, 1, 'Помінятися зміною', '[{"who":"Anna","da":"Hej Mette, kan du bytte vagt med mig på fredag?","ua":"Привіт, Метте, можеш помінятися зі мною зміною в п''ятницю?","me":true},{"who":"Mette","da":"Hvilken vagt har du?","ua":"Яка в тебе зміна?","me":false},{"who":"Anna","da":"Jeg har aftenvagt fra 16 til 22.","ua":"У мене вечірня зміна з 16 до 22.","me":true},{"who":"Mette","da":"Det kan jeg godt. Tager du så min morgenvagt på lørdag?","ua":"Я можу. Тоді візьмеш мою ранкову зміну в суботу?","me":false},{"who":"Anna","da":"Ja, det passer fint. Tak! Jeg skriver det til chefen.","ua":"Так, мені підходить. Дякую! Я напишу про це начальнику.","me":true}]'::jsonb);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (2, 2, 'Запізнююся', '[{"who":"Anna","da":"Hej, jeg er lidt forsinket. Bussen er ikke kommet.","ua":"Привіт, я трохи запізнююся. Автобус не приїхав.","me":true},{"who":"Chef","da":"Okay, hvornår er du her?","ua":"Добре, коли ти будеш?","me":false},{"who":"Anna","da":"Om cirka ti minutter.","ua":"Приблизно за десять хвилин.","me":true},{"who":"Chef","da":"Fint, tak for besked.","ua":"Добре, дякую, що повідомила.","me":false}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (2, 1, 'Якщо запізнюєтеся, напишіть заздалегідь, навіть якщо це 5 хвилин. У Данії цінують, коли попереджають. Коротко: «Jeg er lidt forsinket, jeg er her om 10 minutter.» Цього достатньо.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (2, 1, 'Jeg er sen.', 'Jeg er forsinket.', '«Sen» означає «пізній», але про запізнення кажуть «forsinket». «Jeg kommer for sent» теж правильно.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (2, 2, 'Kan jeg ændre vagt med dig?', 'Kan jeg bytte vagt med dig?', '«Ændre» означає змінити щось. Помінятися зміною з кимось: «bytte vagt med nogen».');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (2, 3, 'Jeg arbejder på weekenden.', 'Jeg arbejder i weekenden.', 'З weekend данці вживають «i»: i weekenden, i dag, i morgen. «På» ставлять з днями тижня: på mandag.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (2, 1, 'Керівнику, запізнення', 'Hej, jeg er lidt forsinket i dag, men jeg er på vej.', 'Привіт, я сьогодні трохи запізнююся, але вже в дорозі.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (2, 2, 'Керівнику, графік', 'Hej, kan du sende mig vagtplanen for næste uge?', 'Привіт, можеш надіслати мені графік на наступний тиждень?');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (2, 3, 'Колезі, обмін змінами', 'Hej! Har du mulighed for at bytte vagt med mig på fredag? Jeg kan tage en af dine vagter i stedet.', 'Привіт! Чи можеш помінятися зі мною зміною в п''ятницю? Я можу взяти замість цього одну з твоїх змін.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (2, 1, 'Як сказати «Я вже в дорозі»?', '["Jeg er her nu.","Jeg er på vej.","Jeg er på arbejde."]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (2, 2, 'Ви хочете помінятися зміною з колегою. Що скажете?', '["Kan jeg bytte vagt med dig?","Kan jeg tage en pause?","Hvornår slutter min vagt?"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (2, 3, 'Що означає «Jeg har fri i morgen»?', '["Завтра я працюю","Завтра я вільна тільки після роботи","У мене завтра вихідний"]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (2, 4, 'Як сказати «Я трохи запізнююся»?', '["Jeg er lidt tidlig.","Jeg er lidt forsinket.","Jeg er lidt sen."]'::jsonb, 1, null);
insert into public.vocab (chapter_id, sort, da, ua) values (2, 1, 'vagt', 'зміна'), (2, 2, 'vagtplan', 'графік змін'), (2, 3, 'morgenvagt', 'ранкова зміна'), (2, 4, 'aftenvagt', 'вечірня зміна'), (2, 5, 'nattevagt', 'нічна зміна'), (2, 6, 'pause', 'перерва'), (2, 7, 'have fri', 'мати вихідний'), (2, 8, 'bytte', 'помінятися'), (2, 9, 'forsinket', 'той, хто запізнюється'), (2, 10, 'overarbejde', 'понаднормова робота');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (3, 'Opgaver & instruktioner', 'Як попросити пояснити завдання, перепитати та перевірити, чи правильно ви зрозуміли інструкцію.', 'Коли начальник швидко пояснює завдання, найважливіше не боятися перепитати. У Данії це нормально і навіть цінується: краще перепитати, ніж зробити неправильно.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(3, 1, 'Hvad skal jeg lave først?', 'Що мені потрібно зробити спочатку?', null),
(3, 2, 'Hvad skal jeg gøre bagefter?', 'Що мені потрібно зробити потім?', null),
(3, 3, 'Kan du vise mig, hvordan man gør?', 'Можеш показати мені, як це робиться?', null),
(3, 4, 'Kan du forklare det igen?', 'Можеш пояснити ще раз?', null),
(3, 5, 'Jeg er ikke helt sikker på, hvad du mener.', 'Я не зовсім впевнена, що ти маєш на увазі.', null),
(3, 6, 'Kan du tale lidt langsommere?', 'Можеш говорити трохи повільніше?', 'Ця фраза рятує в будь-якій розмові. Додайте «undskyld» на початку, і вона звучатиме ще м''якше: «Undskyld, kan du tale lidt langsommere?»'),
(3, 7, 'Jeg forstår ikke den del.', 'Я не розумію цю частину.', null),
(3, 8, 'Hvad betyder det?', 'Що це означає?', null),
(3, 9, 'Skal jeg gøre det nu?', 'Мені зробити це зараз?', null),
(3, 10, 'Skal jeg gøre det på samme måde som sidst?', 'Мені зробити це так само, як минулого разу?', null),
(3, 11, 'Er det sådan, du mener?', 'Ти це маєш на увазі?', null),
(3, 12, 'Har jeg forstået det rigtigt?', 'Я правильно зрозуміла?', 'Після цього запитання коротко повторіть завдання своїми словами. Так ви і перевірите себе, і покажете, що уважно слухали.'),
(3, 13, 'Jeg er færdig med denne opgave.', 'Я закінчила це завдання.', null),
(3, 14, 'Hvad skal jeg tage fat på nu?', 'За що мені взятися зараз?', null),
(3, 15, 'Jeg mangler lige den sidste del.', 'Мені залишилася тільки остання частина.', null),
(3, 16, 'Jeg har brug for lidt hjælp.', 'Мені потрібна невелика допомога.', null),
(3, 17, 'Kan du komme et øjeblik?', 'Можеш підійти на хвилинку?', null),
(3, 18, 'Hvor finder jeg det?', 'Де я можу це знайти?', null),
(3, 19, 'Hvor skal jeg lægge det?', 'Куди мені це покласти?', null),
(3, 20, 'Hvor skal jeg skrive det?', 'Де мені це записати?', null),
(3, 21, 'Hvem skal jeg spørge?', 'Кого мені запитати?', null),
(3, 22, 'Er der en bestemt måde, vi gør det på?', 'Є якийсь певний спосіб, як ми це робимо?', null),
(3, 23, 'Jeg prøver lige.', 'Я зараз спробую.', 'Маленьке слово «lige» данці вживають постійно. Воно пом''якшує фразу: «зараз, швиденько». Jeg prøver lige = я зараз спробую.'),
(3, 24, 'Jeg er næsten færdig.', 'Я майже закінчила.', null),
(3, 25, 'Sig endelig til, hvis jeg gør noget forkert.', 'Обов''язково скажи, якщо я щось роблю неправильно.', '«Endelig» тут не означає «нарешті». У фразі «sig endelig til» це «обов''язково, будь ласка». Дуже ввічливо і дружньо.');
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (3, 1, 'Нове завдання на складі', '[{"who":"Chef","da":"Kan du rydde op på lageret og tjekke de nye varer?","ua":"Можеш прибрати на складі і перевірити нові товари?","me":false},{"who":"Anna","da":"Ja. Hvad skal jeg lave først?","ua":"Так. Що мені зробити спочатку?","me":true},{"who":"Chef","da":"Tjek varerne først, og ryd så op bagefter.","ua":"Спочатку перевір товари, а потім прибери.","me":false},{"who":"Anna","da":"Har jeg forstået det rigtigt: først varerne, så lageret?","ua":"Я правильно зрозуміла: спочатку товари, потім склад?","me":true},{"who":"Chef","da":"Præcis.","ua":"Саме так.","me":false},{"who":"Anna","da":"Hvor skal jeg lægge de nye varer?","ua":"Куди мені покласти нові товари?","me":true},{"who":"Chef","da":"På hylden ved døren.","ua":"На полицю біля дверей.","me":false}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (3, 1, 'Не соромтеся перепитувати. Данські керівники зазвичай пояснюють коротко і чекають, що ви запитаєте, якщо щось незрозуміло. Мовчки кивнути і зробити неправильно гірше, ніж запитати ще раз.');
insert into public.notes (chapter_id, sort, body_ua) values (3, 2, 'Слово «lige» ви чутимете щодня: «Kan du lige komme?», «Jeg skal lige…». Воно робить прохання м''якшим. Спробуйте і ви його додавати.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (3, 1, 'Jeg forstår ikke dig.', 'Jeg forstår dig ikke.', 'Коли після дієслова стоїть коротке слово на кшталт dig, det, ham, «ikke» ставиться після нього: Jeg forstår dig ikke. Jeg kender ham ikke.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (3, 2, 'Kan du forklare mig igen?', 'Kan du forklare det igen?', 'Після «forklare» потрібно сказати, що саме пояснити: forklare det, forklare opgaven.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (3, 3, 'Jeg er færdig med denne opgaven.', 'Jeg er færdig med denne opgave.', 'Після «denne» слово стоїть без закінчення -en: denne opgave, dette spørgsmål.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (3, 1, 'Керівнику, не зрозуміла завдання', 'Hej, jeg er ikke helt sikker på, at jeg har forstået opgaven. Kan du forklare den igen?', 'Привіт, я не зовсім впевнена, що правильно зрозуміла завдання. Можеш пояснити його ще раз?');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (3, 2, 'Керівнику, завдання виконано', 'Hej, jeg er færdig med opgaven. Hvad skal jeg tage fat på nu?', 'Привіт, я закінчила завдання. За що мені взятися зараз?');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (3, 3, 'Колезі, потрібна допомога', 'Hej, har du to minutter? Jeg har brug for lidt hjælp med systemet.', 'Привіт, маєш дві хвилинки? Мені потрібна невелика допомога з системою.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (3, 1, 'Начальник говорить занадто швидко. Що скажете?', '["Kan du tale lidt langsommere?","Kan du komme et øjeblik?","Hvor finder jeg det?"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (3, 2, 'Як перевірити, чи ви правильно зрозуміли?', '["Er det dit?","Hvad laver du?","Har jeg forstået det rigtigt?"]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (3, 3, 'Що означає «Sig endelig til»?', '["Скажи потім","Обов''язково скажи","Скажи нарешті"]'::jsonb, 1, '«Endelig» у цій фразі означає «обов''язково, будь ласка».');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (3, 4, 'Як сказати «Я майже закінчила»?', '["Jeg er næsten færdig.","Jeg er helt færdig.","Jeg er ikke færdig."]'::jsonb, 0, null);
insert into public.vocab (chapter_id, sort, da, ua) values (3, 1, 'opgave', 'завдання'), (3, 2, 'instruktion', 'інструкція'), (3, 3, 'forklare', 'пояснювати'), (3, 4, 'forstå', 'розуміти'), (3, 5, 'vise', 'показувати'), (3, 6, 'færdig', 'готово, закінчено'), (3, 7, 'først', 'спочатку'), (3, 8, 'bagefter', 'потім'), (3, 9, 'rigtigt', 'правильно'), (3, 10, 'forkert', 'неправильно');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (4, 'Møder & samtaler', 'Фрази для зустрічей, обговорень, запитань і висловлення своєї думки.', 'На зустрічах данці говорять спокійно і чекають, що кожен може висловитися. Тут фрази, щоб поставити запитання, погодитися, сказати свою думку або попросити повторити.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(4, 1, 'Hvornår starter mødet?', 'Коли починається зустріч?', null),
(4, 2, 'Hvor skal mødet være?', 'Де буде зустріч?', null),
(4, 3, 'Skal jeg deltage i mødet?', 'Мені потрібно брати участь у зустрічі?', null),
(4, 4, 'Hvad handler mødet om?', 'Про що ця зустріч?', null),
(4, 5, 'Kan du gentage det?', 'Можеш повторити?', null),
(4, 6, 'Jeg vil gerne tilføje noget.', 'Я хотіла б щось додати.', '«Jeg vil gerne» це найввічливіший спосіб сказати «я хотіла б». Використовуйте його замість «jeg vil», яке звучить різкіше.'),
(4, 7, 'Jeg har et spørgsmål.', 'У мене є запитання.', null),
(4, 8, 'Jeg er enig.', 'Я згодна.', null),
(4, 9, 'Det giver mening.', 'Це має сенс.', null),
(4, 10, 'Jeg er ikke helt sikker.', 'Я не зовсім впевнена.', null),
(4, 11, 'Hvad tænker I om det?', 'Що ви про це думаєте?', null),
(4, 12, 'Kan vi tale om det bagefter?', 'Можемо поговорити про це після зустрічі?', null),
(4, 13, 'Jeg skriver det ned.', 'Я це запишу.', null),
(4, 14, 'Jeg sender det senere.', 'Я надішлю це пізніше.', null),
(4, 15, 'Lad os tage det punkt først.', 'Давайте спочатку розглянемо цей пункт.', null),
(4, 16, 'Skal vi gå videre?', 'Можемо рухатися далі?', null),
(4, 17, 'Har alle forstået det?', 'Усі це зрозуміли?', null),
(4, 18, 'Jeg vil lige være sikker på, at jeg har forstået det.', 'Я хочу переконатися, що правильно це зрозуміла.', 'Хороший спосіб перепитати на зустрічі, не перебиваючи. Після неї коротко повторіть, що ви зрозуміли.'),
(4, 19, 'Kan du forklare det med et eksempel?', 'Можеш пояснити це на прикладі?', null),
(4, 20, 'Hvad er næste skridt?', 'Який наступний крок?', null),
(4, 21, 'Hvem tager sig af det?', 'Хто цим займатиметься?', null),
(4, 22, 'Hvornår skal det være færdigt?', 'Коли це має бути готово?', null),
(4, 23, 'Jeg vender tilbage med et svar.', 'Я повернуся з відповіддю.', '«Vende tilbage» дослівно «повернутися», але в роботі це означає «відповім пізніше». Дуже корисно, коли потрібен час подумати.'),
(4, 24, 'Vi kan tage resten senere.', 'Решту можемо обговорити пізніше.', null),
(4, 25, 'Tak for mødet.', 'Дякую за зустріч.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (4, 1, 'Запитання на зустрічі', '[{"who":"Leder","da":"Er der nogen, der har spørgsmål?","ua":"Хтось має запитання?","me":false},{"who":"Anna","da":"Ja, jeg har et spørgsmål. Hvornår skal det være færdigt?","ua":"Так, у мене є запитання. Коли це має бути готово?","me":true},{"who":"Leder","da":"Inden fredag.","ua":"До п''ятниці.","me":false},{"who":"Anna","da":"Og hvem tager sig af kunderne?","ua":"А хто займатиметься клієнтами?","me":true},{"who":"Leder","da":"Det gør Lars. Er det okay?","ua":"Ларс. Це нормально?","me":false},{"who":"Anna","da":"Ja, det giver mening. Jeg skriver det ned.","ua":"Так, це має сенс. Я це запишу.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (4, 1, 'На данських зустрічах нормально мовчати, поки слухаєте, і нормально сказати «Jeg er ikke helt sikker». Ніхто не чекає, що ви одразу маєте готову думку. Фраза «Jeg vender tilbage med et svar» дає вам час подумати.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (4, 1, 'Jeg har enig.', 'Jeg er enig.', '«Бути згодною» данською «være enig», з дієсловом «være», а не «have».');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (4, 2, 'Kan du repetere det?', 'Kan du gentage det?', '«Repetere» кажуть про повторення матеріалу при навчанні. Попросити повторити сказане: «Kan du gentage det?»');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (4, 3, 'Jeg vil tilføje noget.', 'Jeg vil gerne tilføje noget.', 'Без «gerne» фраза звучить як вимога. «Gerne» робить її ввічливою.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (4, 1, 'Колегам, після зустрічі', 'Hej alle, tak for mødet i dag. Jeg sender mine noter senere.', 'Привіт усім, дякую за сьогоднішню зустріч. Я надішлю свої нотатки пізніше.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (4, 2, 'Керівнику, перенести зустріч', 'Hej, kan vi flytte vores møde til i morgen? Jeg har desværre en lægetid i dag.', 'Привіт, можемо перенести нашу зустріч на завтра? На жаль, у мене сьогодні прийом у лікаря.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (4, 1, 'Як ввічливо сказати «Я хотіла б щось додати»?', '["Jeg tilføjer noget nu.","Jeg har noget.","Jeg vil gerne tilføje noget."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (4, 2, 'Як попросити повторити?', '["Kan du tage det?","Kan du gentage det?","Kan du skrive det?"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (4, 3, '«Jeg vender tilbage med et svar» означає:', '["Я відповім пізніше","Я повернуся на роботу","Я не знаю відповіді"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (4, 4, 'Як сказати «Я згодна»?', '["Jeg har enig.","Jeg enig.","Jeg er enig."]'::jsonb, 2, null);
insert into public.vocab (chapter_id, sort, da, ua) values (4, 1, 'møde', 'зустріч'), (4, 2, 'samtale', 'розмова'), (4, 3, 'spørgsmål', 'запитання'), (4, 4, 'svar', 'відповідь'), (4, 5, 'enig', 'згодна, згоден'), (4, 6, 'forslag', 'пропозиція'), (4, 7, 'punkt', 'пункт'), (4, 8, 'referat', 'протокол зустрічі'), (4, 9, 'deadline', 'крайній термін'), (4, 10, 'næste skridt', 'наступний крок');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (5, 'Samtale med chefen', 'Як спокійно поговорити з керівником про роботу, графік, помилки, feedback та години.', 'Розмова з керівником у Данії зазвичай менш формальна, ніж ви можете очікувати. До начальника звертаються на «du» і на ім''я. Тут фрази, щоб спокійно попросити час, feedback або більше годин.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(5, 1, 'Har du et øjeblik?', 'У тебе є хвилинка?', 'Ідеальний початок будь-якої розмови з начальником. Коротко і ввічливо.'),
(5, 2, 'Må jeg lige spørge om noget?', 'Можна я дещо запитаю?', null),
(5, 3, 'Jeg vil gerne tale med dig om min vagtplan.', 'Я хотіла б поговорити з тобою про мій графік.', null),
(5, 4, 'Jeg har et spørgsmål om mine arbejdstider.', 'У мене є запитання щодо мого робочого часу.', null),
(5, 5, 'Kan vi finde et tidspunkt, hvor vi kan tale sammen?', 'Можемо знайти час, щоб поговорити?', null),
(5, 6, 'Jeg vil gerne høre, hvad du tænker.', 'Я хотіла б почути, що ти думаєш.', null),
(5, 7, 'Jeg har brug for lidt mere tid.', 'Мені потрібно трохи більше часу.', null),
(5, 8, 'Jeg kan ikke nå det i dag.', 'Я не встигну зробити це сьогодні.', null),
(5, 9, 'Jeg kan have det færdigt i morgen.', 'Я можу закінчити це завтра.', null),
(5, 10, 'Jeg vil gerne have det forklaret igen.', 'Я хотіла б, щоб мені це пояснили ще раз.', null),
(5, 11, 'Jeg er ikke sikker på, om jeg gør det rigtigt.', 'Я не впевнена, що роблю це правильно.', null),
(5, 12, 'Kan du give mig lidt feedback?', 'Можеш дати мені трохи зворотного зв''язку?', 'Данці часто кажуть просто «feedback», англійською. Це нормально і звучить природно.'),
(5, 13, 'Er der noget, jeg skal gøre anderledes?', 'Є щось, що мені потрібно робити інакше?', null),
(5, 14, 'Hvad synes du, jeg skal fokusere på?', 'Як ти думаєш, на чому мені варто зосередитися?', null),
(5, 15, 'Jeg vil gerne blive bedre til det.', 'Я хотіла б стати в цьому кращою.', null),
(5, 16, 'Jeg har et forslag.', 'У мене є пропозиція.', null),
(5, 17, 'Må jeg foreslå noget?', 'Можна я щось запропоную?', null),
(5, 18, 'Jeg vil gerne spørge om muligheden for flere timer.', 'Я хотіла б запитати про можливість отримати більше годин.', 'Нейтральна фраза, щоб запитати про більше годин без тиску. «Muligheden for» означає «можливість».'),
(5, 19, 'Kan vi tale om min arbejdstid?', 'Можемо поговорити про мій робочий час?', null),
(5, 20, 'Jeg vil gerne høre mere om mine muligheder.', 'Я хотіла б дізнатися більше про свої можливості.', null),
(5, 21, 'Tak, fordi du tog dig tid.', 'Дякую, що знайшов/знайшла час.', 'Дуже теплий спосіб завершити розмову. Данці це цінують.'),
(5, 22, 'Det er jeg glad for at høre.', 'Я рада це чути.', null),
(5, 23, 'Jeg forstår.', 'Я розумію.', null),
(5, 24, 'Det skal jeg nok gøre.', 'Я це зроблю.', null),
(5, 25, 'Jeg vender tilbage til dig.', 'Я повернуся до тебе з відповіддю.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (5, 1, 'Більше годин', '[{"who":"Anna","da":"Har du et øjeblik? Jeg vil gerne tale med dig om mine timer.","ua":"У тебе є хвилинка? Я хотіла б поговорити з тобою про мої години.","me":true},{"who":"Chef","da":"Selvfølgelig. Hvad tænker du?","ua":"Звісно. Що ти думаєш?","me":false},{"who":"Anna","da":"Jeg vil gerne spørge om muligheden for flere timer.","ua":"Я хотіла б запитати про можливість отримати більше годин.","me":true},{"who":"Chef","da":"Det kan vi godt se på. Hvor mange timer tænker du?","ua":"Можемо це розглянути. Скільки годин ти думаєш?","me":false},{"who":"Anna","da":"Cirka 30 timer om ugen.","ua":"Приблизно 30 годин на тиждень.","me":true},{"who":"Chef","da":"Jeg vender tilbage til dig i næste uge.","ua":"Я дам тобі відповідь наступного тижня.","me":false},{"who":"Anna","da":"Tak, fordi du tog dig tid.","ua":"Дякую, що знайшов час.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (5, 1, 'У Данії до керівника звертаються на «du» і на ім''я, і це не неввічливо. Ієрархія пласка: начальник чекає, що ви самі скажете, якщо чогось хочете. Тож не бійтеся просити про розмову: «Har du et øjeblik?» цілком достатньо.');
insert into public.notes (chapter_id, sort, body_ua) values (5, 2, 'Medarbejdersamtale (MUS) це щорічна розмова з керівником про роботу і розвиток. Підготуйте кілька фраз з цього розділу заздалегідь: про feedback, години і що ви хотіли б робити.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (5, 1, 'Kan De give mig feedback?', 'Kan du give mig feedback?', 'Форму «De» (Ви) на роботі в Данії майже не використовують. До начальника звертаються на «du».');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (5, 2, 'Jeg vil have flere timer.', 'Jeg vil gerne have flere timer.', '«Jeg vil have» звучить як вимога. З «gerne» це ввічливе прохання.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (5, 1, 'Керівнику, коротка розмова', 'Hej, har du tid til en kort snak? Jeg har et spørgsmål om mine arbejdstider.', 'Привіт, маєш час коротко поговорити? У мене є запитання щодо мого робочого часу.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (5, 2, 'Керівнику, більше годин', 'Hej, jeg vil gerne høre, om der er mulighed for flere timer. Kan vi tale om det, når det passer dig?', 'Привіт, я хотіла б дізнатися, чи є можливість отримати більше годин. Можемо поговорити про це, коли тобі буде зручно?');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (5, 1, 'Як почати розмову з начальником?', '["Er du færdig?","Har du et øjeblik?","Hvad laver du?"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (5, 2, 'Як звертаються до начальника в Данії?', '["На «du» і на ім''я","На «De» і на прізвище","Тільки «chef»"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (5, 3, 'Як ввічливо попросити більше годин?', '["Jeg vil have flere timer.","Giv mig flere timer.","Jeg vil gerne spørge om muligheden for flere timer."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (5, 4, 'Що сказати в кінці розмови?', '["Vi ses aldrig.","Tak, fordi du tog dig tid.","Det er ikke mit problem."]'::jsonb, 1, null);
insert into public.vocab (chapter_id, sort, da, ua) values (5, 1, 'chef', 'начальник'), (5, 2, 'leder', 'керівник'), (5, 3, 'feedback', 'зворотний зв''язок'), (5, 4, 'timer', 'години'), (5, 5, 'mulighed', 'можливість'), (5, 6, 'forslag', 'пропозиція'), (5, 7, 'fokusere', 'зосереджуватися'), (5, 8, 'medarbejdersamtale', 'щорічна розмова з керівником'), (5, 9, 'anderledes', 'інакше'), (5, 10, 'tid', 'час');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (6, 'Kollegaskab & small talk', 'Повсякденні фрази для нормального спілкування з колегами.', 'Small talk у Данії короткий і легкий: вихідні, погода, кава, відпустка. Не потрібно довгих розмов. Достатньо кількох фраз, щоб колеги відчули, що ви поруч.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(6, 1, 'Hej, hvordan går det?', 'Привіт, як справи?', 'На «Hvordan går det?» зазвичай відповідають коротко: «Godt, tak. Hvad med dig?»'),
(6, 2, 'Hvordan har du det i dag?', 'Як ти сьогодні?', null),
(6, 3, 'Har du haft en god weekend?', 'У тебе були хороші вихідні?', null),
(6, 4, 'Hvad har du lavet i weekenden?', 'Що ти робила на вихідних?', null),
(6, 5, 'Har du nogle planer for weekenden?', 'У тебе є плани на вихідні?', null),
(6, 6, 'Hvordan var din ferie?', 'Як пройшла твоя відпустка?', null),
(6, 7, 'Hvor bor du henne?', 'Де ти живеш?', null),
(6, 8, 'Hvor længe har du arbejdet her?', 'Як давно ти тут працюєш?', null),
(6, 9, 'Kan du lide at arbejde her?', 'Тобі подобається тут працювати?', null),
(6, 10, 'Skal du også have kaffe?', 'Ти теж будеш каву?', null),
(6, 11, 'Skal vi spise frokost sammen?', 'Будемо обідати разом?', null),
(6, 12, 'Jeg tager lige en pause.', 'Я зараз піду на перерву.', null),
(6, 13, 'Vil du med?', 'Підеш зі мною?', null),
(6, 14, 'Jeg er tilbage om lidt.', 'Я скоро повернуся.', null),
(6, 15, 'Hvad laver du efter arbejde?', 'Що ти робиш після роботи?', null),
(6, 16, 'Det var hyggeligt.', 'Було приємно.', '«Hyggeligt» одне з найданськіших слів: приємно, затишно, тепло. Так кажуть після обіду з колегами, розмови чи вечірки.'),
(6, 17, 'Det lyder godt.', 'Звучить добре.', null),
(6, 18, 'Hvor spændende!', 'Як цікаво!', null),
(6, 19, 'Det kan jeg godt forstå.', 'Я це добре розумію.', null),
(6, 20, 'Det kender jeg godt.', 'Мені це знайомо.', null),
(6, 21, 'Jeg har det på samme måde.', 'Я почуваюся так само.', null),
(6, 22, 'God arbejdslyst!', 'Гарної роботи!', 'Так бажають гарної роботи, наприклад коли ви йдете додому, а колега залишається на зміну.'),
(6, 23, 'Vi ses i morgen.', 'Побачимося завтра.', null),
(6, 24, 'God weekend!', 'Гарних вихідних!', null),
(6, 25, 'Vi ses senere.', 'Побачимося пізніше.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (6, 1, 'Кава на перерві', '[{"who":"Kollega","da":"Hej! Skal du også have kaffe?","ua":"Привіт! Ти теж будеш каву?","me":false},{"who":"Anna","da":"Ja tak! Har du haft en god weekend?","ua":"Так, дякую! У тебе були хороші вихідні?","me":true},{"who":"Kollega","da":"Ja, vi var ude at gå en tur i skoven. Hvad med dig?","ua":"Так, ми гуляли в лісі. А в тебе?","me":false},{"who":"Anna","da":"Jeg slappede bare af derhjemme. Det var hyggeligt.","ua":"Я просто відпочивала вдома. Було затишно.","me":true},{"who":"Kollega","da":"Det lyder godt.","ua":"Звучить добре.","me":false}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (6, 1, 'Данці рідко питають дуже особисте на роботі. Вихідні, відпустка, погода і діти це безпечні теми. А фраза «Det lyder godt» підходить як відповідь майже на все.');
insert into public.notes (chapter_id, sort, body_ua) values (6, 2, 'Fredagsbar, спільний обід, торт у п''ятницю: у багатьох данських компаніях є такі маленькі традиції. Приходьте, навіть якщо говорите ще не ідеально. Це найкраща практика мови.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (6, 1, 'Hvordan har du?', 'Hvordan har du det?', 'У цьому запитанні обов''язкове «det»: Hvordan har du det? Відповідь: Jeg har det godt.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (6, 2, 'Det var hyggelig.', 'Det var hyggeligt.', 'Після «det var» прикметник отримує закінчення -t: det var hyggeligt, det var sjovt, det var godt.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (6, 3, 'Vil du komme med mig?', 'Vil du med?', 'Данці кажуть коротко: «Vil du med?» (Підеш зі мною?). Дієслово «komme» тут не потрібне.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (6, 1, 'Колегам, день народження', 'Hej alle! Jeg har fødselsdag i dag, så der er kage i personalerummet kl. 12.', 'Привіт усім! У мене сьогодні день народження, тож о 12 у кімнаті для персоналу буде торт.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (6, 2, 'Колезі, в кінці тижня', 'Tak for i dag, det var hyggeligt at arbejde sammen med dig. God weekend!', 'Дякую за сьогодні, було приємно працювати разом із тобою. Гарних вихідних!');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (6, 1, 'Як відповісти на «Hvordan går det?»', '["Godt, tak. Hvad med dig?","Jeg går hjem.","Det går til kl. 16."]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (6, 2, 'Що означає «Det var hyggeligt»?', '["Було нудно","Було складно","Було приємно"]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (6, 3, 'Як запропонувати колезі каву?', '["Kaffe nu?","Skal du også have kaffe?","Har du kaffe?"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (6, 4, 'Як побажати гарних вихідних?', '["God weekend!","God bedring!","God arbejdslyst!"]'::jsonb, 0, null);
insert into public.vocab (chapter_id, sort, da, ua) values (6, 1, 'kollega', 'колега'), (6, 2, 'kaffe', 'кава'), (6, 3, 'frokost', 'обід'), (6, 4, 'weekend', 'вихідні'), (6, 5, 'ferie', 'відпустка'), (6, 6, 'hyggeligt', 'приємно, затишно'), (6, 7, 'spændende', 'цікаво'), (6, 8, 'planer', 'плани'), (6, 9, 'fødselsdag', 'день народження'), (6, 10, 'kage', 'торт, тістечко');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (7, 'Fejl, problemer & konflikter', 'Що сказати, коли щось пішло не так, виникла помилка або потрібно знайти рішення.', 'Помилки трапляються з усіма. У Данії цінують, коли людина чесно каже «Det var min fejl» і пропонує рішення. Тут фрази, щоб спокійно пояснити проблему і не посилити конфлікт.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(7, 1, 'Der er et problem.', 'Є проблема.', null),
(7, 2, 'Jeg tror, der er sket en fejl.', 'Думаю, сталася помилка.', null),
(7, 3, 'Jeg har lavet en fejl.', 'Я зробила помилку.', null),
(7, 4, 'Det var min fejl.', 'Це була моя помилка.', 'Визнати помилку в Данії це ознака професійності, а не слабкості. Після цієї фрази додайте, що ви зробите: «Jeg skal nok rette det.»'),
(7, 5, 'Jeg beklager.', 'Перепрошую.', null),
(7, 6, 'Jeg skal nok rette det.', 'Я це виправлю.', null),
(7, 7, 'Hvordan kan vi løse det?', 'Як ми можемо це вирішити?', null),
(7, 8, 'Hvad skal jeg gøre nu?', 'Що мені зараз робити?', null),
(7, 9, 'Jeg er ikke sikker på, hvad der gik galt.', 'Я не впевнена, що саме пішло не так.', null),
(7, 10, 'Kan du hjælpe mig med at finde fejlen?', 'Можеш допомогти мені знайти помилку?', null),
(7, 11, 'Det virker ikke.', 'Це не працює.', null),
(7, 12, 'Systemet virker ikke.', 'Система не працює.', null),
(7, 13, 'Jeg kan ikke få det til at virke.', 'Я не можу змусити це працювати.', null),
(7, 14, 'Jeg har prøvet flere gange.', 'Я пробувала кілька разів.', null),
(7, 15, 'Der mangler noget.', 'Чогось не вистачає.', null),
(7, 16, 'Jeg kan ikke finde det.', 'Я не можу це знайти.', null),
(7, 17, 'Det var ikke det, jeg mente.', 'Я мала на увазі не це.', null),
(7, 18, 'Jeg tror, vi har misforstået hinanden.', 'Думаю, ми неправильно зрозуміли одне одного.', 'Дуже м''який спосіб сказати, що виникло непорозуміння. Ніхто не винен, просто зрозуміли по-різному.'),
(7, 19, 'Kan vi tale om det?', 'Можемо про це поговорити?', null),
(7, 20, 'Jeg vil gerne finde en løsning.', 'Я хотіла б знайти рішення.', null),
(7, 21, 'Jeg forstår, hvad du siger.', 'Я розумію, що ти кажеш.', null),
(7, 22, 'Jeg ser det anderledes.', 'Я бачу це інакше.', 'Ввічливий спосіб не погодитися. Звучить спокійно і без агресії.'),
(7, 23, 'Lad os finde ud af det.', 'Давайте розберемося.', null),
(7, 24, 'Det sker.', 'Таке трапляється.', 'Так данці заспокоюють, коли хтось помилився. Якщо вам так кажуть, усе гаразд.'),
(7, 25, 'Jeg sørger for, at det ikke sker igen.', 'Я подбаю, щоб це не повторилося.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (7, 1, 'Помилка із замовленням', '[{"who":"Anna","da":"Undskyld, jeg tror, der er sket en fejl med bestillingen.","ua":"Вибач, думаю, із замовленням сталася помилка.","me":true},{"who":"Chef","da":"Okay, hvad er der sket?","ua":"Добре, що сталося?","me":false},{"who":"Anna","da":"Jeg har bestilt de forkerte varer. Det var min fejl.","ua":"Я замовила не ті товари. Це була моя помилка.","me":true},{"who":"Chef","da":"Det sker. Kan du ringe til leverandøren?","ua":"Таке трапляється. Можеш зателефонувати постачальнику?","me":false},{"who":"Anna","da":"Ja, jeg ringer med det samme. Jeg sørger for, at det ikke sker igen.","ua":"Так, я зателефоную одразу. Я подбаю, щоб це не повторилося.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (7, 1, 'У Данії конфлікти вирішують тихо і прямо, без крику. Краще сказати «Kan vi tale om det?» віч-на-віч, ніж мовчати або скаржитися іншим. Ви маєте право не погоджуватися, головне спокійно.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (7, 1, 'Jeg har gjort en fejl.', 'Jeg har lavet en fejl.', 'Про помилку данці зазвичай кажуть «lave en fejl». «Gøre en fejl» можна почути, але «lave» природніше.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (7, 2, 'Det er ikke min skyld!', 'Jeg tror, vi har misforstået hinanden.', 'Перша фраза граматично правильна, але звучить захисно і різко. Друга допомагає розв''язати ситуацію без конфлікту.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (7, 3, 'Undskyld mig for fejlen.', 'Undskyld fejlen.', 'Коротко і природно: «Undskyld fejlen» або «Jeg beklager fejlen». «Undskyld mig» кажуть, коли хочуть пройти чи звернути на себе увагу.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (7, 1, 'Керівнику, помилка', 'Hej, jeg har desværre lavet en fejl i dag. Jeg har allerede rettet den, men jeg ville gerne sige det til dig.', 'Привіт, на жаль, я сьогодні зробила помилку. Я вже її виправила, але хотіла тобі про це сказати.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (7, 2, 'Колезі, не працює система', 'Hej, systemet virker ikke hos mig. Jeg har prøvet flere gange. Kan du hjælpe?', 'Привіт, у мене не працює система. Я пробувала кілька разів. Можеш допомогти?');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (7, 1, 'Як визнати помилку?', '["Det er ikke mit problem.","Det virker ikke.","Det var min fejl."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (7, 2, 'Колега каже «Det sker». Що це означає?', '["Це погано","Таке трапляється","Це станеться"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (7, 3, 'Як ввічливо не погодитися?', '["Jeg ser det anderledes.","Du tager fejl!","Nej, nej, nej."]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (7, 4, 'Як сказати «Це не працює»?', '["Det arbejder ikke.","Det går ikke hjem.","Det virker ikke."]'::jsonb, 2, 'Про речі і системи кажуть «virke», а не «arbejde».');
insert into public.vocab (chapter_id, sort, da, ua) values (7, 1, 'fejl', 'помилка'), (7, 2, 'problem', 'проблема'), (7, 3, 'løsning', 'рішення'), (7, 4, 'rette', 'виправити'), (7, 5, 'misforståelse', 'непорозуміння'), (7, 6, 'virke', 'працювати (про річ)'), (7, 7, 'beklage', 'перепрошувати'), (7, 8, 'konflikt', 'конфлікт'), (7, 9, 'uenig', 'не згодна'), (7, 10, 'skyld', 'провина');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (8, 'Telefon, beskeder & e-mail', 'Готові фрази для дзвінків, повідомлень та електронної пошти.', 'Телефонувати данською часто найстрашніше, бо не видно обличчя. Не соромтеся просити говорити повільніше або надіслати інформацію SMS. Тут фрази для дзвінків, повідомлень і коротких листів.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(8, 1, 'Hej, det er Anna.', 'Привіт, це Анна.', null),
(8, 2, 'Hvem taler jeg med?', 'З ким я розмовляю?', null),
(8, 3, 'Kan du tale lidt langsommere?', 'Можеш говорити трохи повільніше?', null),
(8, 4, 'Jeg hørte ikke det sidste.', 'Я не почула останнє.', null),
(8, 5, 'Kan du gentage det?', 'Можеш повторити?', null),
(8, 6, 'Kan du stave det?', 'Можеш продиктувати це по літерах?', 'Корисно для імен, адрес і назв, які важко розчути по телефону.'),
(8, 7, 'Kan du sende det på sms?', 'Можеш надіслати це SMS?', null),
(8, 8, 'Jeg sender dig en besked.', 'Я надішлю тобі повідомлення.', null),
(8, 9, 'Jeg har sendt dig en mail.', 'Я надіслала тобі електронний лист.', null),
(8, 10, 'Har du set min besked?', 'Ти бачив/бачила моє повідомлення?', null),
(8, 11, 'Jeg vender tilbage senere.', 'Я відповім пізніше.', null),
(8, 12, 'Jeg ringer tilbage om lidt.', 'Я передзвоню трохи пізніше.', null),
(8, 13, 'Jeg kan ikke tale lige nu.', 'Я зараз не можу говорити.', 'Якщо телефонують у незручний момент, це нормальна фраза. Додайте «Må jeg ringe tilbage om lidt?»'),
(8, 14, 'Må jeg ringe tilbage?', 'Можна я передзвоню?', null),
(8, 15, 'Kan du sende mig adressen?', 'Можеш надіслати мені адресу?', null),
(8, 16, 'Kan du sende mig oplysningerne?', 'Можеш надіслати мені інформацію?', null),
(8, 17, 'Jeg har et spørgsmål.', 'У мене є запитання.', null),
(8, 18, 'Jeg skriver lige for at spørge om noget.', 'Я пишу, щоб дещо запитати.', null),
(8, 19, 'Tak for din besked.', 'Дякую за твоє повідомлення.', null),
(8, 20, 'Jeg har modtaget din mail.', 'Я отримала твій лист.', null),
(8, 21, 'Jeg vender tilbage så hurtigt som muligt.', 'Я відповім якомога швидше.', null),
(8, 22, 'Vedhæftet finder du dokumentet.', 'У додатку ти знайдеш документ.', 'Типова фраза для e-mail. «Vedhæftet» означає «у вкладенні».'),
(8, 23, 'Giv mig endelig besked.', 'Обов''язково дай мені знати.', null),
(8, 24, 'God dag.', 'Гарного дня.', null),
(8, 25, 'Venlig hilsen', 'З повагою.', 'Стандартне завершення листа. Часто пишуть скорочено: «Vh» або «Mvh» (Med venlig hilsen).');
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (8, 1, 'Дзвінок щодо зміни', '[{"who":"Anna","da":"Hej, det er Anna. Jeg ringer angående min vagt i morgen.","ua":"Привіт, це Анна. Я телефоную щодо моєї зміни завтра.","me":true},{"who":"Kontoret","da":"Hej Anna. Du starter klokken syv.","ua":"Привіт, Анно. Ти починаєш о сьомій.","me":false},{"who":"Anna","da":"Undskyld, jeg hørte ikke det sidste. Kan du gentage det?","ua":"Вибач, я не почула останнє. Можеш повторити?","me":true},{"who":"Kontoret","da":"Klokken syv. Jeg sender det også på sms.","ua":"О сьомій. Я також надішлю це SMS.","me":false},{"who":"Anna","da":"Tusind tak. Hav en god dag.","ua":"Щиро дякую. Гарного дня.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (8, 1, 'Якщо боїтеся телефонувати, заздалегідь запишіть 2-3 фрази на папері. А фраза «Kan du sende det på sms?» рятує завжди: ви отримаєте інформацію письмово і зможете спокійно перечитати.');
insert into public.notes (chapter_id, sort, body_ua) values (8, 2, 'У данських листах не потрібні довгі формальності. «Hej» та ім''я на початку і «Venlig hilsen» в кінці підходять майже для всіх ситуацій, навіть для листа начальнику чи HR.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (8, 1, 'Kære chef, jeg skriver til Dem…', 'Hej Mette, jeg skriver for at…', 'Данські робочі листи прості. Звертаються на ім''я і на «du». Форма «Dem» звучить дуже старомодно.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (8, 2, 'Jeg ringer tilbage om lidt tid.', 'Jeg ringer tilbage om lidt.', '«Om lidt» вже означає «трохи згодом». Слово «tid» тут зайве.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (8, 1, 'Керівнику, e-mail', 'Hej Mette
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (8, 2, 'Колезі, SMS', 'Hej, jeg kan ikke tale lige nu. Jeg ringer tilbage om lidt.', 'Привіт, я зараз не можу говорити. Передзвоню трохи згодом.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (8, 1, 'Ви не почули кінець речення по телефону. Що скажете?', '["Jeg er på vej.","Jeg hørte ikke det sidste.","Jeg har ikke tid."]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (8, 2, 'Як попросити надіслати інформацію SMS?', '["Kan du sende det på sms?","Kan du ringe til mig?","Kan du stave det?"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (8, 3, 'Що означає «Vh» в кінці листа?', '["Дуже важливо","Чекаю відповіді","З повагою"]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (8, 4, 'Як сказати «Я передзвоню трохи згодом»?', '["Jeg ringede i går.","Jeg ringer tilbage om lidt.","Jeg ringer aldrig."]'::jsonb, 1, null);
insert into public.vocab (chapter_id, sort, da, ua) values (8, 1, 'ringe', 'телефонувати'), (8, 2, 'besked', 'повідомлення'), (8, 3, 'sms', 'SMS'), (8, 4, 'mail', 'електронний лист'), (8, 5, 'svare', 'відповідати'), (8, 6, 'vedhæftet', 'у вкладенні'), (8, 7, 'stave', 'диктувати по літерах'), (8, 8, 'adresse', 'адреса'), (8, 9, 'angående', 'щодо'), (8, 10, 'venlig hilsen', 'з повагою');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (9, 'Løn, ferie & vilkår', 'Лексика про зарплату, відпустку, контракт, години та умови роботи.', 'Про зарплату, відпустку і контракт питати нормально і правильно. Тут фрази, щоб розібратися з lønseddel, спланувати ferie і зрозуміти свої умови.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(9, 1, 'Hvornår får jeg min løn?', 'Коли я отримую зарплату?', null),
(9, 2, 'Hvor kan jeg se min lønseddel?', 'Де я можу переглянути розрахунковий лист?', 'Lønseddel це розрахунковий лист. У Данії його часто отримують через e-Boks. Там видно години, податок і відпускні (feriepenge).'),
(9, 3, 'Jeg har et spørgsmål om min løn.', 'У мене є запитання щодо моєї зарплати.', null),
(9, 4, 'Jeg tror, der er en fejl på min lønseddel.', 'Думаю, у моєму розрахунковому листі є помилка.', null),
(9, 5, 'Kan du hjælpe mig med at forstå min lønseddel?', 'Можеш допомогти мені зрозуміти мій розрахунковий лист?', null),
(9, 6, 'Hvor mange feriedage har jeg?', 'Скільки в мене днів відпустки?', null),
(9, 7, 'Jeg vil gerne holde ferie i næste uge.', 'Я хотіла б піти у відпустку наступного тижня.', 'Про відпустку данці кажуть «holde ferie». «Tage ferie» теж зрозуміють, але «holde» звучить природніше.'),
(9, 8, 'Kan jeg holde fri på fredag?', 'Чи можу я бути вихідною в п''ятницю?', null),
(9, 9, 'Hvordan søger jeg om ferie?', 'Як мені подати заявку на відпустку?', null),
(9, 10, 'Skal jeg registrere min ferie et sted?', 'Мені потрібно десь зареєструвати відпустку?', null),
(9, 11, 'Hvordan fungerer ferie her?', 'Як тут працює система відпусток?', null),
(9, 12, 'Hvad står der i min kontrakt?', 'Що написано в моєму контракті?', null),
(9, 13, 'Hvor mange timer er jeg ansat til?', 'На скільки годин я працевлаштована?', '«Være ansat til» означає, на скільки годин вас узяли на роботу за договором.'),
(9, 14, 'Er der mulighed for flere timer?', 'Чи є можливість отримати більше годин?', null),
(9, 15, 'Er der mulighed for færre timer?', 'Чи є можливість працювати менше годин?', null),
(9, 16, 'Hvornår udløber min kontrakt?', 'Коли закінчується мій контракт?', null),
(9, 17, 'Skal min kontrakt forlænges?', 'Мій контракт потрібно продовжити?', null),
(9, 18, 'Hvem kan jeg spørge om det?', 'Кого я можу про це запитати?', null),
(9, 19, 'Jeg vil gerne være sikker på, at jeg har forstået det rigtigt.', 'Я хочу бути впевненою, що правильно це зрозуміла.', null),
(9, 20, 'Kan du forklare reglerne?', 'Можеш пояснити правила?', null),
(9, 21, 'Er der noget, jeg skal være opmærksom på?', 'Є щось, на що мені потрібно звернути увагу?', null),
(9, 22, 'Hvornår får jeg besked?', 'Коли я отримаю повідомлення?', null),
(9, 23, 'Tak for informationen.', 'Дякую за інформацію.', null),
(9, 24, 'Det vil jeg gerne vide mere om.', 'Я хотіла б дізнатися про це більше.', null),
(9, 25, 'Kan vi tale om det senere?', 'Можемо поговорити про це пізніше?', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (9, 1, 'Питання про зарплату', '[{"who":"Anna","da":"Hej, jeg har et spørgsmål om min lønseddel.","ua":"Привіт, у мене є запитання щодо мого розрахункового листа.","me":true},{"who":"HR","da":"Selvfølgelig. Hvad drejer det sig om?","ua":"Звісно. Про що йдеться?","me":false},{"who":"Anna","da":"Jeg tror, der mangler nogle timer. Jeg arbejdede ekstra i sidste uge.","ua":"Думаю, бракує кількох годин. Минулого тижня я працювала додатково.","me":true},{"who":"HR","da":"Det tjekker jeg. Har du registreret timerne i systemet?","ua":"Я це перевірю. Ти зареєструвала години в системі?","me":false},{"who":"Anna","da":"Ja, det har jeg. Tak for hjælpen.","ua":"Так, зареєструвала. Дякую за допомогу.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (9, 1, 'Якщо думаєте, що в зарплаті помилка, скажіть про це спокійно. Це звичайна ситуація, і її швидко виправляють. Фраза «Jeg tror, der er en fejl på min lønseddel» звучить нейтрально і нікого не звинувачує.');
insert into public.notes (chapter_id, sort, body_ua) values (9, 2, 'Feriepenge це відпускні гроші, які накопичуються з кожної зарплати. Запитайте на роботі, як у вас працює система відпусток: «Hvordan fungerer ferie her?»');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (9, 1, 'Hvornår får jeg min betaling?', 'Hvornår får jeg min løn?', 'Про зарплату данці кажуть «løn». «Betaling» це оплата, наприклад рахунку.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (9, 2, 'Jeg vil gerne tage ferie næste uge.', 'Jeg vil gerne holde ferie i næste uge.', 'Природніше «holde ferie», і перед «næste uge» потрібне «i».');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (9, 1, 'HR, відпустка', 'Hej, jeg vil gerne holde ferie i uge 29 og 30. Hvordan søger jeg om det?', 'Привіт, я хотіла б піти у відпустку на 29-му і 30-му тижнях. Як мені подати заявку?');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (9, 2, 'HR, помилка в зарплаті', 'Hej, jeg tror, der er en fejl på min lønseddel for marts. Kan du hjælpe mig med at se på det?', 'Привіт, думаю, у моєму розрахунковому листі за березень є помилка. Можеш допомогти мені це перевірити?');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (9, 1, 'Що таке «lønseddel»?', '["Розрахунковий лист","Графік змін","Контракт"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (9, 2, 'Як сказати «Я хотіла б піти у відпустку наступного тижня»?', '["Jeg holder altid fri.","Jeg havde ferie i går.","Jeg vil gerne holde ferie i næste uge."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (9, 3, 'Як запитати, чи можна отримати більше годин?', '["Har du tid?","Er der mulighed for flere timer?","Hvor mange timer er klokken?"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (9, 4, '«Hvornår udløber min kontrakt?» означає:', '["Коли закінчується мій контракт?","Коли підписати контракт?","Де мій контракт?"]'::jsonb, 0, null);
insert into public.vocab (chapter_id, sort, da, ua) values (9, 1, 'løn', 'зарплата'), (9, 2, 'lønseddel', 'розрахунковий лист'), (9, 3, 'ferie', 'відпустка'), (9, 4, 'feriedage', 'дні відпустки'), (9, 5, 'feriepenge', 'відпускні'), (9, 6, 'kontrakt', 'контракт'), (9, 7, 'vilkår', 'умови'), (9, 8, 'skat', 'податок'), (9, 9, 'overenskomst', 'колективний договір'), (9, 10, 'ansat', 'працевлаштована');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (10, 'Chef, HR & arbejdsplads', 'Фрази для спілкування з керівником, HR та для орієнтації на робочому місці.', 'Перші тижні на новому місці повні запитань: кому писати, де реєструвати години, де лежать речі. Тут фрази, щоб знайти потрібну людину і потрібну інформацію.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(10, 1, 'Hvem er min nærmeste leder?', 'Хто мій безпосередній керівник?', '«Nærmeste leder» це ваш безпосередній керівник, людина, до якої ви звертаєтеся першою.'),
(10, 2, 'Hvem skal jeg kontakte?', 'З ким мені потрібно зв''язатися?', null),
(10, 3, 'Hvor finder jeg personalepolitikken?', 'Де я можу знайти правила для працівників?', null),
(10, 4, 'Hvor finder jeg medarbejderhåndbogen?', 'Де я можу знайти довідник працівника?', 'У багатьох компаніях є довідник працівника з правилами: хвороба, відпустка, перерви. Його варто прочитати.'),
(10, 5, 'Hvordan registrerer jeg mine timer?', 'Як мені реєструвати свої години?', null),
(10, 6, 'Hvor registrerer jeg min arbejdstid?', 'Де я реєструю свій робочий час?', null),
(10, 7, 'Hvad gør jeg, hvis jeg kommer for sent?', 'Що мені робити, якщо я запізнююся?', null),
(10, 8, 'Hvem skal jeg melde mig syg til?', 'Кому я повинна повідомити про хворобу?', null),
(10, 9, 'Hvor finder jeg information om ferie?', 'Де я можу знайти інформацію про відпустку?', null),
(10, 10, 'Hvor er personalerummet?', 'Де знаходиться кімната для персоналу?', null),
(10, 11, 'Hvor er toilettet?', 'Де туалет?', null),
(10, 12, 'Hvor kan jeg hænge min jakke?', 'Де я можу повісити куртку?', null),
(10, 13, 'Hvor kan jeg finde de nødvendige materialer?', 'Де я можу знайти необхідні матеріали?', null),
(10, 14, 'Hvem har ansvar for det?', 'Хто за це відповідає?', null),
(10, 15, 'Hvem kan hjælpe mig med det?', 'Хто може мені з цим допомогти?', null),
(10, 16, 'Er der nogle regler, jeg skal kende?', 'Є якісь правила, які я повинна знати?', null),
(10, 17, 'Hvad forventer I af mig?', 'Чого ви від мене очікуєте?', null),
(10, 18, 'Er der noget, jeg skal læse?', 'Є щось, що мені потрібно прочитати?', null),
(10, 19, 'Hvor finder jeg informationen?', 'Де я можу знайти інформацію?', null),
(10, 20, 'Hvem kan jeg spørge, hvis jeg er i tvivl?', 'Кого я можу запитати, якщо сумніваюся?', null),
(10, 21, 'Jeg vil gerne være sikker på, at jeg gør det rigtigt.', 'Я хочу бути впевненою, що роблю це правильно.', null),
(10, 22, 'Tak for hjælpen.', 'Дякую за допомогу.', null),
(10, 23, 'Det er noteret.', 'Я це запам''ятала/занотувала.', 'Коротка ділова відповідь: «прийнято, записала». Добре підходить для повідомлень і пошти.'),
(10, 24, 'Det skal jeg nok huske.', 'Я це обов''язково запам''ятаю.', null),
(10, 25, 'Jeg vender tilbage, når jeg ved mere.', 'Я повернуся з відповіддю, коли дізнаюся більше.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (10, 1, 'Розмова з HR', '[{"who":"Anna","da":"Undskyld, hvem skal jeg melde mig syg til?","ua":"Вибачте, кому я маю повідомляти про хворобу?","me":true},{"who":"HR","da":"Du ringer til din nærmeste leder, inden din vagt starter.","ua":"Ти телефонуєш своєму безпосередньому керівнику до початку зміни.","me":false},{"who":"Anna","da":"Okay. Og hvor registrerer jeg min arbejdstid?","ua":"Добре. А де я реєструю свій робочий час?","me":true},{"who":"HR","da":"I appen. Jeg viser dig det bagefter.","ua":"У застосунку. Я покажу тобі потім.","me":false},{"who":"Anna","da":"Tak for hjælpen. Det er noteret.","ua":"Дякую за допомогу. Я записала.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (10, 1, 'Якщо не знаєте, кого запитати, запитайте про це прямо: «Hvem kan jeg spørge, hvis jeg er i tvivl?». У Данії ніхто не чекає, що новенька знає все одразу.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (10, 1, 'Hvem er min boss?', 'Hvem er min nærmeste leder?', 'Англійське «boss» можна почути в розмові, але на роботі кажуть «leder» або «chef».');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (10, 2, 'Hvor er toilet?', 'Hvor er toilettet?', 'Коли питаєте про конкретне місце, слово отримує закінчення: toilettet, køkkenet, personalerummet.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (10, 1, 'HR, нова у відділі', 'Hej, jeg er ny i afdelingen. Hvor kan jeg finde medarbejderhåndbogen?', 'Привіт, я нова у відділі. Де я можу знайти довідник працівника?');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (10, 2, 'Керівнику, підтвердження', 'Tak for informationen. Det er noteret.', 'Дякую за інформацію. Записала.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (10, 1, 'Хто такий «nærmeste leder»?', '["Найближчий колега","Директор компанії","Безпосередній керівник"]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (10, 2, 'Як запитати, де туалет?', '["Hvornår er toilettet?","Hvor er toilettet?","Hvem er toilettet?"]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (10, 3, 'Як сказати «Дякую за допомогу»?', '["Tak for hjælpen.","Tak for mad.","Tak for sidst."]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (10, 4, '«Det er noteret» означає:', '["Це заборонено","Це нотатка","Прийнято, я записала"]'::jsonb, 2, null);
insert into public.vocab (chapter_id, sort, da, ua) values (10, 1, 'leder', 'керівник'), (10, 2, 'HR', 'відділ кадрів'), (10, 3, 'afdeling', 'відділ'), (10, 4, 'personalerum', 'кімната для персоналу'), (10, 5, 'regler', 'правила'), (10, 6, 'registrere', 'реєструвати'), (10, 7, 'arbejdstid', 'робочий час'), (10, 8, 'ansvar', 'відповідальність'), (10, 9, 'medarbejder', 'працівник'), (10, 10, 'i tvivl', 'у сумніві');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (11, 'Ny på arbejdspladsen', 'Фрази для першого дня та перших тижнів на новій роботі.', 'Перший день на новій роботі завжди хвилює. Фрази з цього розділу допоможуть познайомитися, попросити все показати і не боятися сказати «Jeg lærer stadig».');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(11, 1, 'Det er min første dag.', 'Сьогодні мій перший день.', null),
(11, 2, 'Jeg er ny her.', 'Я тут новенька.', null),
(11, 3, 'Jeg hedder Anna.', 'Мене звати Анна.', null),
(11, 4, 'Jeg glæder mig til at komme i gang.', 'Я рада почати.', '«Glæde sig til» означає з радістю чекати чогось. Дуже позитивна фраза: jeg glæder mig til weekenden, jeg glæder mig til at arbejde med jer.'),
(11, 5, 'Hvor skal jeg starte?', 'З чого мені почати?', null),
(11, 6, 'Hvem skal jeg gå til?', 'До кого мені звернутися?', null),
(11, 7, 'Kan du vise mig rundt?', 'Можеш показати мені все тут?', null),
(11, 8, 'Hvor er køkkenet?', 'Де кухня?', null),
(11, 9, 'Hvor er personalerummet?', 'Де кімната для персоналу?', null),
(11, 10, 'Hvor lægger vi vores ting?', 'Де ми залишаємо свої речі?', null),
(11, 11, 'Hvordan fungerer det her?', 'Як це тут працює?', null),
(11, 12, 'Hvad plejer I at gøre?', 'Що ви зазвичай робите?', null),
(11, 13, 'Er der noget særligt, jeg skal vide?', 'Є щось особливе, що мені потрібно знати?', null),
(11, 14, 'Hvem arbejder jeg sammen med?', 'З ким я працюю разом?', null),
(11, 15, 'Hvem er ansvarlig i dag?', 'Хто сьогодні відповідальний?', null),
(11, 16, 'Hvad er min opgave?', 'Яке моє завдання?', null),
(11, 17, 'Kan du vise mig det en gang til?', 'Можеш показати мені ще раз?', null),
(11, 18, 'Jeg lærer stadig.', 'Я все ще вчуся.', 'Чесна і сильна фраза. Колеги поставляться з розумінням і охочіше допоможуть.'),
(11, 19, 'Du må gerne sige til, hvis jeg gør noget forkert.', 'Можеш сказати, якщо я щось роблю неправильно.', null),
(11, 20, 'Jeg spørger hellere en gang for meget.', 'Я краще перепитаю зайвий раз.', 'Ця фраза показує, що ви відповідальна. На новому місці це найкраща стратегія.'),
(11, 21, 'Tak, det hjælper meget.', 'Дякую, це дуже допомагає.', null),
(11, 22, 'Det er rart at møde jer.', 'Приємно з вами познайомитися.', null),
(11, 23, 'Jeg glæder mig til at arbejde sammen med jer.', 'Я рада працювати разом із вами.', null),
(11, 24, 'Vi ses i morgen.', 'Побачимося завтра.', null),
(11, 25, 'Tak for en god første dag.', 'Дякую за хороший перший день.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (11, 1, 'Перший день', '[{"who":"Kollega","da":"Hej, du må være den nye?","ua":"Привіт, ти, мабуть, новенька?","me":false},{"who":"Anna","da":"Ja, jeg hedder Anna. Det er min første dag.","ua":"Так, мене звати Анна. Сьогодні мій перший день.","me":true},{"who":"Kollega","da":"Velkommen! Jeg hedder Sofie. Skal jeg vise dig rundt?","ua":"Ласкаво просимо! Я Софі. Показати тобі все?","me":false},{"who":"Anna","da":"Ja tak, det vil jeg gerne. Hvor lægger vi vores ting?","ua":"Так, дякую, дуже хочу. Де ми залишаємо свої речі?","me":true},{"who":"Kollega","da":"Derovre i skabene. Og køkkenet er lige her.","ua":"Он там, у шафках. А кухня ось тут.","me":false},{"who":"Anna","da":"Tak, det hjælper meget.","ua":"Дякую, це дуже допомагає.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (11, 1, 'Перші тижні на новій роботі нікому не легкі, особливо іншою мовою. Скажіть колегам, що вчите данську: «Jeg lærer dansk, så sig endelig til, hvis jeg ikke forstår.» Більшість зрадіє і говоритиме повільніше.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (11, 1, 'Mit navn er Anna.', 'Jeg hedder Anna.', '«Mit navn er» граматично правильно, але звучить офіційно. Данці знайомляться просто: «Jeg hedder Anna.»');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (11, 2, 'Det er rart at møde du.', 'Det er rart at møde dig.', 'Після дієслова потрібна форма «dig» (тебе), а не «du» (ти).');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (11, 1, 'Колегам, знайомство', 'Hej alle sammen! Jeg hedder Anna og er ny her. Jeg glæder mig til at arbejde sammen med jer.', 'Привіт усім! Мене звати Анна, я тут новенька. Я рада працювати разом із вами.');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (11, 2, 'Керівнику, після першого дня', 'Tak for en god første dag. Vi ses i morgen!', 'Дякую за хороший перший день. Побачимося завтра!');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (11, 1, 'Як представитися?', '["Hedder jeg Anna.","Jeg hedder Anna.","Jeg er Anna navn."]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (11, 2, 'Як попросити, щоб вам усе показали?', '["Kan du vise mig rundt?","Kan du gå rundt?","Kan du se mig?"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (11, 3, 'Як сказати «Я все ще вчуся»?', '["Jeg lærer aldrig.","Jeg har lært.","Jeg lærer stadig."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (11, 4, '«Jeg glæder mig til at komme i gang» означає:', '["Я йду додому","Я рада почати","Я вже закінчила"]'::jsonb, 1, null);
insert into public.vocab (chapter_id, sort, da, ua) values (11, 1, 'ny', 'нова, новий'), (11, 2, 'første dag', 'перший день'), (11, 3, 'vise rundt', 'показати все'), (11, 4, 'køkken', 'кухня'), (11, 5, 'skab', 'шафка'), (11, 6, 'ansvarlig', 'відповідальний'), (11, 7, 'lære', 'вчитися'), (11, 8, 'velkommen', 'ласкаво просимо'), (11, 9, 'rart', 'приємно'), (11, 10, 'hedde', 'називатися');
insert into public.chapters (id, title_da, description_ua, intro_ua) values (12, 'Dansk på dansk', 'Короткі живі фрази, які данці кажуть щодня.', 'Це маленькі фрази, які ви чутимете на роботі щодня. Вони короткі, але саме вони роблять вашу данську живою. Вивчіть їх як готові блоки, не розбираючи граматику.');
insert into public.phrases (chapter_id, sort, da, ua, explanation_ua) values
(12, 1, 'Det kommer an på.', 'Це залежить.', 'Дуже данська відповідь на складне запитання. Можна додати, від чого залежить: «Det kommer an på vejret».'),
(12, 2, 'Det giver mening.', 'Це має сенс.', null),
(12, 3, 'Det lyder godt.', 'Звучить добре.', null),
(12, 4, 'Det er helt fint.', 'Все добре.', null),
(12, 5, 'Det er ikke noget problem.', 'Це не проблема.', null),
(12, 6, 'Det kan jeg godt.', 'Я можу це зробити.', null),
(12, 7, 'Det kan jeg ikke lige nu.', 'Я не можу цього зараз.', null),
(12, 8, 'Jeg er lige på vej.', 'Я вже в дорозі.', null),
(12, 9, 'Jeg vender tilbage.', 'Я повернуся з відповіддю.', null),
(12, 10, 'Jeg skal nok gøre det.', 'Я це зроблю.', null),
(12, 11, 'Jeg er ikke sikker.', 'Я не впевнена.', null),
(12, 12, 'Jeg er i tvivl.', 'Я сумніваюся.', '«Være i tvivl» означає сумніватися, вагатися. Дуже часто: «Hvis du er i tvivl, så spørg.»'),
(12, 13, 'Jeg forstår.', 'Я розумію.', null),
(12, 14, 'Jeg forstår ikke.', 'Я не розумію.', null),
(12, 15, 'Kan du hjælpe mig?', 'Можеш мені допомогти?', null),
(12, 16, 'Kan du forklare det?', 'Можеш це пояснити?', null),
(12, 17, 'Kan du gentage det?', 'Можеш це повторити?', null),
(12, 18, 'Hvad mener du?', 'Що ти маєш на увазі?', null),
(12, 19, 'Hvad skal jeg gøre?', 'Що мені робити?', null),
(12, 20, 'Hvad er næste skridt?', 'Який наступний крок?', null),
(12, 21, 'Jeg er næsten færdig.', 'Я майже закінчила.', null),
(12, 22, 'Jeg er færdig.', 'Я закінчила.', null),
(12, 23, 'Jeg har brug for hjælp.', 'Мені потрібна допомога.', null),
(12, 24, 'Jeg har et spørgsmål.', 'У мене є запитання.', null),
(12, 25, 'Må jeg spørge om noget?', 'Можна дещо запитати?', null),
(12, 26, 'Et øjeblik.', 'Хвилинку.', null),
(12, 27, 'Lige et øjeblik.', 'Буквально хвилинку.', 'Знову маленьке «lige»: воно пом''якшує прохання почекати.'),
(12, 28, 'Jeg kommer om lidt.', 'Я скоро прийду.', null),
(12, 29, 'Jeg er tilbage om lidt.', 'Я скоро повернуся.', null),
(12, 30, 'Vi ses senere.', 'Побачимося пізніше.', null);
insert into public.dialogues (chapter_id, sort, title_ua, lines) values (12, 1, 'Хвилинку!', '[{"who":"Kollega","da":"Kan du hjælpe mig med kasserne?","ua":"Можеш допомогти мені з коробками?","me":false},{"who":"Anna","da":"Lige et øjeblik. Jeg er næsten færdig.","ua":"Хвилинку. Я майже закінчила.","me":true},{"who":"Kollega","da":"Det er helt fint.","ua":"Все добре.","me":false},{"who":"Anna","da":"Så, nu kan jeg godt. Hvad skal jeg gøre?","ua":"Все, тепер можу. Що мені робити?","me":true},{"who":"Kollega","da":"Bare bær dem ud til bilen.","ua":"Просто віднеси їх до машини.","me":false},{"who":"Anna","da":"Det er ikke noget problem.","ua":"Це не проблема.","me":true}]'::jsonb);
insert into public.notes (chapter_id, sort, body_ua) values (12, 1, 'Ці фрази як цеглинки. Не намагайтеся перекладати їх дослівно. Просто запам''ятайте, в якій ситуації їх кажуть, і повторюйте вголос. Через тиждень вони почнуть з''являтися у вашій мові самі.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (12, 1, 'Det afhænger.', 'Det kommer an på.', 'У повсякденній розмові «це залежить» данською майже завжди «det kommer an på». «Det afhænger af…» теж є, але тільки з продовженням.');
insert into public.mistakes (chapter_id, sort, wrong, better, why_ua) values (12, 2, 'Et moment.', 'Et øjeblik.', '«Et øjeblik» (дослівно «один погляд») це найприродніший спосіб сказати «хвилинку».');
insert into public.messages (chapter_id, sort, audience_ua, da, ua) values (12, 1, 'Колезі', 'Et øjeblik, jeg kommer om lidt.', 'Хвилинку, я скоро прийду.');
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (12, 1, 'Що означає «Det kommer an på»?', '["Це залежить","Це приходить","Це не важливо"]'::jsonb, 0, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (12, 2, 'Як сказати «Хвилинку»?', '["Et minut nu.","En tid.","Et øjeblik."]'::jsonb, 2, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (12, 3, 'Колега просить про допомогу, а ви зайняті. Що скажете?', '["Vi ses senere.","Lige et øjeblik.","Nej tak."]'::jsonb, 1, null);
insert into public.exercises (chapter_id, sort, question_ua, options, correct, explain_ua) values (12, 4, 'Як сказати «Я сумніваюся»?', '["Jeg er i tvivl.","Jeg er tvivl.","Jeg har tvivlet."]'::jsonb, 0, null);
insert into public.vocab (chapter_id, sort, da, ua) values (12, 1, 'øjeblik', 'мить, хвилинка'), (12, 2, 'tvivl', 'сумнів'), (12, 3, 'næsten', 'майже'), (12, 4, 'færdig', 'готово'), (12, 5, 'lige', 'щойно, зараз'), (12, 6, 'hjælp', 'допомога'), (12, 7, 'senere', 'пізніше'), (12, 8, 'skridt', 'крок'), (12, 9, 'mene', 'мати на увазі'), (12, 10, 'om lidt', 'трохи згодом');
